detaileddescription.para:
Usage example: classCustomStream:publicsf::SoundStream
{
public:

[[nodiscard]]boolopen(conststd::string&location)
{
//Openthesourceandgetaudiosettings
...
unsignedintchannelCount=2;//Stereo
unsignedintsampleRate=44100;//44100Hz

//Initializethestream--important!
initialize(channelCount,sampleRate,{sf::SoundChannel::FrontLeft,sf::SoundChannel::FrontRight});
returntrue;
}

private:

boolonGetData(Chunk&data)override
{
//Fillthechunkwithaudiodatafromthestreamsource
//(note:mustnotbeemptyifyouwanttocontinueplaying)
data.samples=...;

//Returntruetocontinueplaying
data.sampleCount=...;
returntrue;
}

voidonSeek(sf::TimetimeOffset)override
{
//Changethecurrentpositioninthestreamsource
...
}
};

//Usage
CustomStreamstream;
stream.open("path/to/stream");
stream.play();
